#!/usr/bin/env python3
"""Generate the deterministic HyperFrames desktop editor composition."""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def waveform_path() -> str:
    source = ROOT / "assets" / "waveform.json"
    if source.exists():
        peaks = json.loads(source.read_text())["peaks"]
    else:
        # Deterministic fallback so the composition can be authored before assets land.
        peaks = [0.18 + ((i * 37) % 71) / 100 for i in range(1440)]
    if len(peaks) != 1440:
        step = max(1, len(peaks) / 1440)
        peaks = [peaks[min(len(peaks) - 1, int(i * step))] for i in range(1440)]
    top, bottom, mid = [], [], 28
    for x, raw in enumerate(peaks):
        amp = max(1.5, min(25, float(raw) * 25))
        top.append(f"{x},{mid-amp:.2f}")
        bottom.append(f"{x},{mid+amp:.2f}")
    return "M" + " L".join(top) + " L" + " L".join(reversed(bottom)) + " Z"


