def segment_markup(kind: str, idx: int, start: float, end: float, classes: str) -> str:
    width = end - start
    if kind == "v":
        label = '<span class="clipname">aixscool_take01.mp4</span>' if idx in (0, 6) else ''
        return f'<div class="seg vseg v{idx} {classes}" style="left:{start:.3f}px;width:{width:.3f}px;background-image:url(assets/filmstrip.jpg);background-position:-{start:.3f}px 0">{label}</div>'
    seam = '<i class="handle"></i><i class="fadecurve"></i>' if idx == 4 else ''
    return f'<div class="seg aseg a{idx} {classes}" style="left:{start:.3f}px;width:{width:.3f}px"><div class="waveinner" data-layout-allow-overflow style="left:-{start:.3f}px"><svg viewBox="0 0 1440 56" preserveAspectRatio="none"><path d="__WAVE__" fill="#5dd2d1" opacity=".84"/></svg></div>{seam}</div>'


def build() -> None:
    bounds = [(0,269.981),(269.981,319.476),(319.476,448.670),(448.670,484.773),(484.773,533.510),(533.510,559.399),(559.399,1440)]
    classes = ["", "vg1", "after1", "vg2 after1", "after2 after1", "vg3 after2 after1", "after3 after2 after1"]
    aclasses = [c.replace("vg", "ag") for c in classes]
    videos = "".join(segment_markup("v", i, a, b, classes[i]) for i,(a,b) in enumerate(bounds))
    audios = "".join(segment_markup("a", i, a, b, aclasses[i]) for i,(a,b) in enumerate(bounds)).replace("__WAVE__", waveform_path())
    thumbs = "".join(f'<div class="asset"><div class="thumb" style="background-image:url(assets/thumb-{i:02d}.jpg)"><span class="dur">00:{20+i:02d}</span></div><div class="asset-name">aixscool_take{i:02d}.mp4</div></div>' for i in range(1,9))
    cuts = "".join(f'<div class="cutmark c{i+1}" style="left:{x:.3f}px"></div>' for i,x in enumerate([269.981,319.476,448.670,484.773,533.510,559.399]))
    out = HTML.replace("__THUMBS__", thumbs).replace("__VIDEO_SEGMENTS__", videos).replace("__AUDIO_SEGMENTS__", audios).replace("__CUTMARKS__", cuts)
    (ROOT / "index.html").write_text(out)


if __name__ == "__main__":
    build()
